require_once __DIR__.'/../config/app.php';require_admin();if(is_post()&&isset($_POST['delete_id'])){verify_csrf();$id=(int)$_POST['delete_id'];db()->prepare('UPDATE products SET is_active=0 WHERE id=?')->execute([$id]);flash('success','Produk dinonaktifkan dan tidak lagi tampil di katalog.');redirect('admin/products.php');}
$q=trim($_GET['q']??'');$params=[];$where='1=1';if($q!==''){$where='(p.name LIKE ? OR p.sku LIKE ?)';$params=['%'.$q.'%','%'.$q.'%'];}$stmt=db()->prepare("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE $where ORDER BY p.created_at DESC");$stmt->execute($params);$products=$stmt->fetchAll();$pageTitle='Produk';require APP_ROOT.'/includes/admin-header.php';
?>
<div class="d-flex flex-wrap gap-3 justify-content-between align-items-center mb-4"><form class="d-flex gap-2"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Cari nama atau SKU"><button class="btn btn-light"><i class="bi bi-search"></i></button></form><a class="btn btn-primary" href="<?= url('admin/product-create.php') ?>"><i class="bi bi-plus-lg me-1"></i>Tambah Produk</a></div><div class="admin-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody><?php foreach($products as $product):?><tr><td><div class="d-flex align-items-center gap-3"><img class="product-thumb" src="<?= e(product_image($product['image'])) ?>"><div><strong><?= e($product['name']) ?></strong><div class="small text-muted"><?= e($product['sku']) ?></div></div></div></td><td><?= e($product['category_name']) ?></td><td><?= rupiah($product['price']) ?></td><td><span class="badge text-bg-<?= $product['stock']<=$product['minimum_stock']?'warning':'success' ?>"><?= $product['stock'] ?></span></td><td><span class="badge text-bg-<?= $product['is_active']?'success':'secondary' ?>"><?= $product['is_active']?'Aktif':'Nonaktif' ?></span></td><td class="text-end"><a class="btn btn-sm btn-light" href="<?= url('admin/product-edit.php?id='.$product['id']) ?>"><i class="bi bi-pencil"></i></a><?php if($product['is_active']):?><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="delete_id" value="<?= $product['id'] ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Nonaktifkan produk ini dari katalog?"><i class="bi bi-eye-slash"></i></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
